// Build the core of a data explorer.

// 1) groupBy(records, keyFn)

// 2) uniqueBy(records, keyFn)

// 3) summarize(records)

// 4) safeGet(records, index)

tests.code:
const fn = new Function(code + "\nreturn { groupBy, uniqueBy, summarize, safeGet };");
const { groupBy } = fn();
const recs = [
  { id: 1, kind: "fruit", score: 2 },
  { id: 2, kind: "veg", score: 5 },
  { id: 3, kind: "fruit", score: 9 },
];
const out = groupBy(recs, (r) => r.kind);
if (out.fruit.length !== 2 || out.veg.length !== 1) throw new Error("groupBy should bucket records by the keyFn result.");
if (out.fruit[0].id !== 1 || out.fruit[1].id !== 3) throw new Error("groupBy must preserve record order within each bucket.");

const fn = new Function(code + "\nreturn { groupBy, uniqueBy, summarize, safeGet };");
const { uniqueBy } = fn();
const recs = [
  { id: 1, kind: "fruit" },
  { id: 2, kind: "veg" },
  { id: 3, kind: "fruit" },
];
const out = uniqueBy(recs, (r) => r.kind);
if (out.length !== 2 || out[0].id !== 1 || out[1].id !== 2) throw new Error("uniqueBy should keep only the FIRST record per key, in order.");

const fn = new Function(code + "\nreturn { groupBy, uniqueBy, summarize, safeGet };");
const { summarize } = fn();
const recs = [{ score: 4 }, { score: 8 }, { score: 6 }];
const s = summarize(recs);
if (s.count !== 3) throw new Error("count should be the number of records.");
if (Math.abs(s.avgScore - 6) > 1e-9) throw new Error("avgScore should be the mean of the score fields (6 here).");
if (!s.top || s.top.score !== 8) throw new Error("top should be the WHOLE record with the highest score.");
const empty = summarize([]);
if (empty.count !== 0 || empty.avgScore !== 0 || empty.top !== null) throw new Error("Empty input must yield { count: 0, avgScore: 0, top: null }.");

const fn = new Function(code + "\nreturn { groupBy, uniqueBy, summarize, safeGet };");
const { safeGet } = fn();
const recs = [{ id: 1 }, { id: 2 }];
if (safeGet(recs, 0)?.id !== 1) throw new Error("safeGet(recs, 0) should return the first record.");
if (safeGet(recs, 5) !== null) throw new Error("Out-of-range index must return null, not throw.");
if (safeGet(recs, 1.5) !== null) throw new Error("Non-integer index must return null.");
if (safeGet(recs, -1) !== null) throw new Error("Negative index must return null.");
